#pragma once
// The Weyl-Heisenberg SIC frame generated by a fiducial, in binary64 (complex128).
//
// Convention (docs/sicx.md#mathematical-conventions): omega = exp(2 pi i/d), tau = -exp(pi i/d),
//   X|j> = |j+1>, Z|j> = omega^j |j>, D_p = tau^(p1 p2) X^p1 Z^p2, so
//   (D_p psi)_k = tau^(-p1 p2) omega^(p2 k) psi_(k-p1).
//
// SicFrame streams the d^2 vectors D_p psi without storing them (d = 2048 gives 4.2M vectors of
// length 2048, 137 GB as complex128), and computes overlaps with one length-d FFT per shift p1:
//   <psi|D_p|psi>  = tau^(p1 p2)  sum_j conj(psi_(j+p1)) psi_j omega^(+p2 j),
//   <D_p psi|phi>  = tau^(p1 p2)  sum_k conj(psi_(k-p1)) phi_k omega^(-p2 k),
// O(d^2 log d) for power-of-two d (O(d^3) otherwise) and O(d) working storage per row.
// All values are floating-point diagnostics, not certificates. A SicFrame is immutable after
// construction; concurrent calls need distinct outputs.

#include <algorithm>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <limits>
#include <numbers>
#include <stdexcept>
#include <vector>

#include "sic/core/types.hpp"
#include "sic/core/weyl_heisenberg.hpp"
#include "sic/error.hpp"
#include "sic/limits.hpp"

namespace sic::core {

// Returns psi / ||psi|| computed with scaling (no overflow/underflow for finite input).
// Throws sic::Error(ErrorKind::invalid_argument) for an empty, zero or nonfinite vector. *norm
// receives ||psi||.
Vector normalized_copy(const Vector& psi, Real* norm = nullptr);

class SicFrame {
 public:
  // Takes a copy of the fiducial; normalizes it unless normalize == false.
  // Dimensions above maximum_dimension or 2^30 throw sic::Error(resource).
  explicit SicFrame(const Vector& fiducial, bool normalize = true,
                    uint64_t maximum_dimension = sic::kDefaultCoreDimension);

  int dim() const { return static_cast<int>(d_); }
  const Vector& fiducial() const { return psi_; }
  Real input_norm() const { return input_norm_; }

  // exp(pi i m / d) for any integer m.
  Complex root_2d(std::int64_t m) const { return wh_.root_2d(m); }
  // tau^k = exp(pi i k (d+1) / d).
  Complex tau_pow(std::int64_t k) const { return wh_.tau_pow(k); }

  // out[k] = (D_(p1,p2) v)_k for an arbitrary vector v (out must not alias v). O(d).
  void displace(std::int64_t p1, std::int64_t p2, const Complex* v, Complex* out) const {
    wh_.displace(p1, p2, v, out);
  }
  // out = D_(p1,p2) psi.
  void vector(std::int64_t p1, std::int64_t p2, Vector& out) const;
  // The d vectors with fixed p1: out[p2 * d + k] = (D_(p1,p2) psi)_k, p2 = 0..d-1. O(d^2).
  void row_block(std::int64_t p1, Vector& out) const;
  // Calls fn(p1, p2, const Complex* v) for all p in {0..d-1}^2, p1-major, with v = D_p psi
  // (valid during the call only). O(d^3) time in total, O(d) memory.
  template <class Fn>
  void for_each_vector(Fn&& fn) const {
    Vector buffer(d_);
    for (std::size_t p1 = 0; p1 < d_; ++p1)
      for (std::size_t p2 = 0; p2 < d_; ++p2) {
        displace(static_cast<std::int64_t>(p1), static_cast<std::int64_t>(p2), psi_.data(),
                 buffer.data());
        fn(static_cast<std::int64_t>(p1), static_cast<std::int64_t>(p2),
           static_cast<const Complex*>(buffer.data()));
      }
  }

  // out[p2] = <psi|D_(p1,p2)|psi>, p2 = 0..d-1.
  void overlap_row(std::int64_t p1, Vector& out) const { wh_.overlap_row(p1, psi_, out); }
  // out[p2] = <D_(p1,p2) psi|phi>, p2 = 0..d-1, for any phi of length d.
  void cross_overlap_row(std::int64_t p1, const Vector& phi, Vector& out) const {
    wh_.cross_overlap_row(p1, psi_, phi, out);
  }
  // All overlaps, index p1 * d + p2. O(d^2) storage.
  std::vector<Complex> overlaps() const;

 private:
  std::size_t d_;
  WeylHeisenberg wh_;
  Vector psi_;
  Real input_norm_ = 0;

  static std::size_t check_dim(std::size_t n, uint64_t maximum_dimension);
};

// Pull-style iterator over the d^2 SIC vectors, p1-major: while (s.next(v)) use(s.p1(), s.p2(), v).
class SicVectorStream {
 public:
  // Borrows frame; frame must outlive this mutable, owner-thread iterator.
  explicit SicVectorStream(const SicFrame& frame) : frame_(frame) {}
  SicVectorStream(SicFrame&&) = delete;
  SicVectorStream(const SicFrame&&) = delete;
  bool next(Vector& out);
  std::int64_t p1() const { return cur1_; }
  std::int64_t p2() const { return cur2_; }

 private:
  const SicFrame& frame_;
  std::int64_t p1_ = 0, p2_ = 0, cur1_ = -1, cur2_ = -1;
};

// Binary64 SIC check of a (not necessarily normalized) fiducial.
struct SicCheck {
  int d = 0;
  Real input_norm = 0;         // ||psi|| as given
  Real norm_defect = 0;        // | ||psi|| - 1 |
  Real max_overlap_error = 0;  // max_{p != 0 mod d} | |<psi|D_p|psi>|^2 - 1/(d+1) |, psi normalized
  std::int64_t worst_p1 = 0, worst_p2 = 0;
  Real parseval_defect = 0;  // | sum_p |<psi|D_p|psi>|^2 - d |  (an identity for unit psi)
  bool passes(Real tol) const {
    return d > 0 && std::isfinite(max_overlap_error) && tol >= 0 && max_overlap_error <= tol;
  }
};

SicCheck check_sic(const SicFrame& frame);
SicCheck check_sic(const Vector& psi);

}  // namespace sic::core
